class.description:
Seul le premier enfant [BTNode] est utilisé. Sans script, un décorateur transmet le statut de son enfant (et échoue s'il n'en a pas). Pour un décorateur personnalisé, étendre cette classe et redéfinir [method BTNode._tick] en appelant [code]get_child_node().execute(delta)[/code].
[codeblock]
# Décorateur par script : n'exécute l'enfant que si l'agent est au sol.
extends BTDecorator

func _tick(delta: float) -> int:
	if not get_agent().is_on_floor():
		return FAILURE
	return get_child_node().execute(delta)
[/codeblock]
